import {
    Component,
    ChangeDetectionStrategy,
    Input,
    OnChanges,
    SimpleChanges,
    ChangeDetectorRef,
    OnDestroy,
} from '@angular/core';
import { Subject, takeUntil } from 'rxjs';
import { getImagePath } from 'app/core/misc';
import { APP_NAMES } from 'app/core/app-names.enum';
import { ICountry } from '@imunify360-api/lists';
import { CountryService } from 'app/services/country';

@Component({
    selector: 'i360-country-cell',
    templateUrl: './country-cell.component.html',
    styleUrls: ['./country-cell.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CountryCellComponent implements OnChanges, OnDestroy {
    @Input() country: Partial<ICountry> | null;

    countryName: string = '';
    flagsPath: string = `${getImagePath()}/${APP_NAMES.OTHER_ROOT}/flags/`;

    private destroy$ = new Subject<void>();

    constructor(
        private cdr: ChangeDetectorRef,
        private countryService: CountryService,
    ) {
    }

    ngOnChanges(changes: SimpleChanges): void {
        if ('country' in changes && !!this.country?.code) {
            this.setCountryName(this.country as ICountry);
        }
    }

    ngOnDestroy(): void {
        this.destroy$.next();
    }

    private setCountryName(country: ICountry): void {
        if (!!country.name) {
            this.countryName = country.name;
            return;
        }

        this.countryService.loaded
            .pipe(takeUntil(this.destroy$))
            .subscribe(loaded => {
                if (loaded) {
                    this.countryName = this.countryService.getCountryNameByCode(country?.code);
                    this.cdr.markForCheck();
                }
            });
    }
}
